function noAdjacentOnes(n) {
  const result = [];
  const path = [];
  const build = () => {
    if (path.length === n) {
      result.push(path.join(""));
      return;
    }
    path.push("0");                              // a 0 is always allowed
    build();
    path.pop();
    if (path[path.length - 1] !== "1") {         // prune: a 1 right after a 1 can never work
      path.push("1");
      build();
      path.pop();
    }
  };
  build();
  return result;
}

List<String> noAdjacentOnes(int n) {
    List<String> result = new ArrayList<>();
    build(n, new StringBuilder(), result);
    return result;
}

void build(int n, StringBuilder path, List<String> result) {
    if (path.length() == n) {
        result.add(path.toString());
        return;
    }
    path.append('0');                         // a 0 is always allowed
    build(n, path, result);
    path.deleteCharAt(path.length() - 1);
    if (path.length() == 0 || path.charAt(path.length() - 1) != '1') {   // prune
        path.append('1');
        build(n, path, result);
        path.deleteCharAt(path.length() - 1);
    }
}

void build(int n, string& path, vector<string>& result) {
    if ((int)path.size() == n) {
        result.push_back(path);
        return;
    }
    path.push_back('0');                      // a 0 is always allowed
    build(n, path, result);
    path.pop_back();
    if (path.empty() || path.back() != '1') { // prune: a 1 right after a 1 can never work
        path.push_back('1');
        build(n, path, result);
        path.pop_back();
    }
}

vector<string> noAdjacentOnes(int n) {
    vector<string> result;
    string path;
    build(n, path, result);
    return result;
}
